changeSet.sql:
UPDATE users SET avatar_url = 'https://' || avatar_url WHERE avatar_url IS NOT NULL AND avatar_url NOT ILIKE 'http://%' AND avatar_url NOT ILIKE 'https://%';
UPDATE dogs SET media_url = 'https://' || media_url WHERE media_url IS NOT NULL AND media_url NOT ILIKE 'http://%' AND media_url NOT ILIKE 'https://%';
UPDATE posts SET image_url = 'https://' || image_url WHERE image_url IS NOT NULL AND image_url NOT ILIKE 'http://%' AND image_url NOT ILIKE 'https://%';
